class Master:
    def __init__(self):
        self.datos = {}
        self.replicas = []

    def escribir_sincrona(self, clave, valor):
        self.datos[clave] = valor
        confirmaciones = 0
        for replica in self.replicas:
            replica.datos[clave] = valor
            confirmaciones += 1
        return confirmaciones == len(self.replicas)

    def escribir_asincrona(self, clave, valor):
        self.datos[clave] = valor
        pendientes = list(self.replicas)
        return pendientes  # se replican despues, el cliente ya recibio OK

class Replica:
    def __init__(self, nombre):
        self.nombre = nombre
        self.datos = {}

master = Master()
r1, r2 = Replica("r1"), Replica("r2")
master.replicas = [r1, r2]

ok = master.escribir_sincrona("pedido:1", "pagado")
print(f"Escritura sincrona confirmada por todas las replicas: {ok}")
print(f"r1 ve pedido:1 = {r1.datos.get('pedido:1')}")

pendientes = master.escribir_asincrona("pedido:2", "pendiente")
print(f"Escritura asincrona: cliente ya recibio OK, replicas pendientes = {[p.nombre for p in pendientes]}")
print(f"r1 ve pedido:2 antes de replicar = {r1.datos.get('pedido:2')}")
for r in pendientes:
    r.datos["pedido:2"] = master.datos["pedido:2"]
print(f"r1 ve pedido:2 despues de replicar = {r1.datos.get('pedido:2')}")
